import "core-js/modules/es.array.push.js";
import { useDisplay } from "vuetify/lib/framework.mjs";
import { list_all_visit_locations } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar
  },
  data: () => ({
    height: 0,
    page: 1,
    currentPage: 1,
    itemsPerPage: 10,
    totalItems: 0,
    SnackBarComponent: {},
    CommonVuetifyObj: {},
    tableData: [],
    TableHeaders: [{
      title: "Name",
      value: "location_name",
      sortable: false
    }, {
      title: "Address",
      value: "location_address",
      sortable: false
    }, {
      title: "Location Type ",
      value: "location_type",
      sortable: false
    }, {
      title: "Created On ",
      value: "location_created_on",
      sortable: false
    }, {
      title: "Created By",
      value: "location_created_by",
      sortable: false
    }, {
      title: "Actions",
      value: "actions",
      sortable: false
    }]
  }),
  computed: {
    pageCount() {
      return Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async mounted() {
    this.CommonVuetifyObj = useDisplay();
    this.fetch_locationtype();
  },
  methods: {
    async fetch_locationtype() {
      this.tableLoading = true;
      this.tableData = [];
      try {
        let result = await API.graphql(graphqlOperation(list_all_visit_locations, {
          input: {
            nextToken: null,
            limit: 100,
            location_verification_status: "VERIFIED"
          }
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_all_visit_locations);
        if (response.Status === "SUCCESS") {
          this.tableLoading = false;
          this.tableData = response.data || [];
          this.totalItems = this.tableData.length;
        } else {
          this.tableLoading = false;
          this.tableData = [];
          this.totalItems = 0;
        }
      } catch (error) {
        this.tableLoading = false;
        this.tableData = [];
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    getConvertedDate(location_created_on) {
      if (!location_created_on) return "-";
      const date = new Date(location_created_on * 1000);
      if (isNaN(date.getTime())) return "Invalid Date";
      const [yyyy, mm, dd] = date.toISOString().substring(0, 10).split("-");
      return `${dd}-${mm}-${yyyy}`;
    }
  }
};
